  "vk_colar_aplicar": "Check and apply",
  "vk_conf_resumo": "{n} pairs recognised — {a} of ALTA confidence, {m} MEDIA.",
  "vk_conf_ignoradas": "{n} line(s) ignored: outside the format, or pointing at a subject not on the list.",
  "vk_conf_nada": "No valid pair in this answer.",
  "vk_conf_media": "Also include the {n} MEDIA-confidence pairs?\n\nMEDIA means “equivalent with a caveat”. If one enters wrongly, you skip a subject you have not studied.",
  "vk_marca_ja_visto": "↗ seen in {c} {n} days ago",
